import sys
import math

def main():
    n = int(sys.stdin.readline())
    res = []
    current = list(range(1, n+1))
    for _ in range(n):
        g = current[0]
        for num in current[1:]:
            g = math.gcd(g, num)
            if g == 1:
                break
        res.append(g)
        if len(current) == 1:
            current.pop()
        else:
            current.remove(max(current))

    print(' '.join(map(str, res)))

main()
